-- 화양 공동관리: 실제 RLS/RPC를 합성 851세대와 세 사용자로 검증한다.
begin;
select no_plan();
create function pg_temp.hid(prefix text, n integer) returns uuid language sql immutable as $$ select md5('hwayang-test-' || prefix || n::text)::uuid $$;
insert into public.project(id,organization_id,name) values ('1283e198-5043-4027-96d6-edcc7a6686c6','10000000-0000-4000-8000-000000000001','Synthetic Hwayang');
insert into public.project_member(id,project_id,user_id,role) values
(pg_temp.hid('member',1),'1283e198-5043-4027-96d6-edcc7a6686c6','30000000-0000-4000-8000-0000000000c1','PROJECT_ADMIN'),
(pg_temp.hid('member',2),'1283e198-5043-4027-96d6-edcc7a6686c6','30000000-0000-4000-8000-00000000000a','COUNSELOR'),
(pg_temp.hid('member',3),'1283e198-5043-4027-96d6-edcc7a6686c6','30000000-0000-4000-8000-00000000000b','COUNSELOR');
insert into public.project_unit(unit_id,project_id,building_no,unit_no) select pg_temp.hid('unit',n),'1283e198-5043-4027-96d6-edcc7a6686c6','101',n::text from generate_series(1,851) n;
insert into public.customer(id,project_id,name,phone,phone_normalized,assigned_counselor_id)
select pg_temp.hid('customer',n),'1283e198-5043-4027-96d6-edcc7a6686c6','Synthetic '||n,'010'||lpad(n::text,8,'0'),'010'||lpad(n::text,8,'0'),case when n%3=0 then null else pg_temp.hid('member',2+n%2) end from generate_series(1,851) n;
insert into public.contract(contract_id,project_id,unit_id,customer_id,contract_status) select pg_temp.hid('contract',n),'1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',n),pg_temp.hid('customer',n),'ACTIVE' from generate_series(1,851) n;
insert into public.unit_occupancy_status(project_id,unit_id,contract_id) select '1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',n),pg_temp.hid('contract',n) from generate_series(1,851) n;
insert into public.consultation(project_id,customer_id,unit_id,counselor_id,created_by,content,consulted_at) select '1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('customer',(n%851)+1),pg_temp.hid('unit',(n%851)+1),pg_temp.hid('member',3),pg_temp.hid('member',3),'Synthetic history',now()-n*interval '1 minute' from generate_series(1,2033) n;
insert into public.project_unit(unit_id,project_id,building_no,unit_no) values(pg_temp.hid('otherunit',1),'20000000-0000-4000-8000-000000000001','999','1');
insert into public.contract(contract_id,project_id,customer_id,unit_id,contract_status) values(pg_temp.hid('othercontract',1),'20000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-0000000000a1',pg_temp.hid('otherunit',1),'ACTIVE');
insert into public.brokerage_office(id,project_id,name) values(pg_temp.hid('otheroffice',1),'20000000-0000-4000-8000-000000000001','Synthetic other');
create function pg_temp.login(u text) returns void language sql as $$ select set_config('request.jwt.claim.sub',u,true)::void $$;

select pg_temp.login('30000000-0000-4000-8000-0000000000c1');
set local role authenticated;
select is((select count(*) from public.project_unit where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),851::bigint,'actor 1: all project_unit visible');
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),851::bigint,'actor 1: all customer visible');
select is((select count(*) from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='Synthetic history'),2033::bigint,'actor 1: all consultation visible');
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and assigned_counselor_id is null),283::bigint,'actor 1: unassigned visible');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','actor-1',p_legacy_grade:='A',p_next_contact_at:=now()+interval '1 day',p_move_in_status:='CONTACTED')$$,'actor 1: unassigned consultation and occupancy write');
select is((select created_by from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='actor-1'),pg_temp.hid('member',1),'actor 1: actual logged-in author');
select is((select counselor_id from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='actor-1'),pg_temp.hid('member',1),'actor 1: actual counselor');
select lives_ok($$select public.generate_report('1283e198-5043-4027-96d6-edcc7a6686c6',current_date,'MOVE_IN','DAILY','{}')$$,'actor 1: worklog report generation');
select lives_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','Synthetic office 1')$$,'actor 1: brokerage write');
select lives_ok($$select public.save_move_in_unit_deal('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('contract',3),pg_temp.hid('customer',3),'CONSENTED','IN_PROGRESS',true,false,false)$$,'actor 1: deal write');
reset role;

select pg_temp.login('30000000-0000-4000-8000-00000000000a');
set local role authenticated;
select is((select count(*) from public.project_unit where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),851::bigint,'actor 2: all project_unit visible');
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),851::bigint,'actor 2: all customer visible');
select is((select count(*) from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='Synthetic history'),2033::bigint,'actor 2: all consultation visible');
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and assigned_counselor_id is null),283::bigint,'actor 2: unassigned visible');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','actor-2',p_legacy_grade:='A',p_next_contact_at:=now()+interval '1 day',p_move_in_status:='CONTACTED')$$,'actor 2: unassigned consultation and occupancy write');
select is((select created_by from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='actor-2'),pg_temp.hid('member',2),'actor 2: actual logged-in author');
select is((select counselor_id from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='actor-2'),pg_temp.hid('member',2),'actor 2: actual counselor');
select lives_ok($$select public.generate_report('1283e198-5043-4027-96d6-edcc7a6686c6',current_date,'MOVE_IN','DAILY','{}')$$,'actor 2: worklog report generation');
select lives_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','Synthetic office 2')$$,'actor 2: brokerage write');
select lives_ok($$select public.save_move_in_unit_deal('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('contract',3),pg_temp.hid('customer',3),'CONSENTED','IN_PROGRESS',true,false,false)$$,'actor 2: deal write');
reset role;

select pg_temp.login('30000000-0000-4000-8000-00000000000b');
set local role authenticated;
select is((select count(*) from public.project_unit where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),851::bigint,'actor 3: all project_unit visible');
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),851::bigint,'actor 3: all customer visible');
select is((select count(*) from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='Synthetic history'),2033::bigint,'actor 3: all consultation visible');
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and assigned_counselor_id is null),283::bigint,'actor 3: unassigned visible');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','actor-3',p_legacy_grade:='A',p_next_contact_at:=now()+interval '1 day',p_move_in_status:='CONTACTED')$$,'actor 3: unassigned consultation and occupancy write');
select is((select created_by from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='actor-3'),pg_temp.hid('member',3),'actor 3: actual logged-in author');
select is((select counselor_id from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content='actor-3'),pg_temp.hid('member',3),'actor 3: actual counselor');
select lives_ok($$select public.generate_report('1283e198-5043-4027-96d6-edcc7a6686c6',current_date,'MOVE_IN','DAILY','{}')$$,'actor 3: worklog report generation');
select lives_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','Synthetic office 3')$$,'actor 3: brokerage write');
select lives_ok($$select public.save_move_in_unit_deal('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('contract',3),pg_temp.hid('customer',3),'CONSENTED','IN_PROGRESS',true,false,false)$$,'actor 3: deal write');
reset role;

select pg_temp.login('30000000-0000-4000-8000-00000000000a');
set local role authenticated;
select is((select count(*) from public.customer where project_id='20000000-0000-4000-8000-000000000002'),0::bigint,'other project read denied');
select throws_ok($$select public.generate_report('20000000-0000-4000-8000-000000000002',current_date,'MOVE_IN','DAILY','{}')$$,'42501',null,'other project write denied');
select throws_ok($$select public.generate_report('20000000-0000-4000-8000-000000000001',current_date,'MOVE_IN','DAILY','{}')$$,'42501',null,'non-Hwayang counselor report remains denied');
select throws_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),'50000000-0000-4000-8000-0000000000a1','OUTBOUND','bad')$$,'23514',null,'cross-project customer IDOR denied');
select throws_ok($$select public.create_move_in_consultation('20000000-0000-4000-8000-000000000001',pg_temp.hid('unit',3),'50000000-0000-4000-8000-0000000000a1','OUTBOUND','bad')$$,'23514',null,'cross-project unit IDOR denied');
select throws_ok($$select public.create_contract('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('customer',3),pg_temp.hid('unit',3))$$,'42501',null,'contract admin-only');
select throws_ok($$select public.cancel_contract('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('contract',3),'test')$$,'42501',null,'cancel admin-only');
select throws_ok($$select public.transfer_contract_holder('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('contract',3),pg_temp.hid('customer',4))$$,'42501',null,'transfer admin-only');
select throws_ok($$select public.assign_move_in_customers('1283e198-5043-4027-96d6-edcc7a6686c6',array[pg_temp.hid('customer',3)],pg_temp.hid('member',2))$$,'42501',null,'assignment admin-only');
select throws_ok($$select public.update_customer_phone('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('customer',3),'01012345678','01000000003')$$,'42501',null,'phone admin-only');
-- 같은 세션이 두 프로젝트 멤버여도 resource 조합은 일치해야 한다.
select throws_ok($$select public.update_unit_occupancy_status('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('othercontract',1),p_move_in_status:='CONTACTED')$$,'23514',null,'cross-project contract IDOR denied');
select throws_ok($$select public.save_move_in_unit_deal('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('othercontract',1),pg_temp.hid('customer',3),'CONSENTED','IN_PROGRESS',true,false,false)$$,'23514',null,'deal contract IDOR denied');
select throws_ok($$select public.save_move_in_unit_deal('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('contract',3),pg_temp.hid('customer',4),'CONSENTED','IN_PROGRESS',true,false,false)$$,'23514',null,'same-project wrong holder denied');
select throws_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','bad',p_office_id:=pg_temp.hid('otheroffice',1))$$,'23514',null,'brokerage office IDOR denied');
select throws_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('otherunit',1),pg_temp.hid('customer',3),'OUTBOUND','bad')$$,'23514',null,'Hwayang request with foreign unit denied');
select is((select count(*) from public.customer where project_id='20000000-0000-4000-8000-000000000001' and assigned_counselor_id is distinct from '40000000-0000-4000-8000-00000000000a'::uuid),0::bigint,'other project assigned-customer RLS unchanged');
select is((select count(*) from public.project_unit where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and unit_id=pg_temp.hid('otherunit',1)),0::bigint,'cross-project unit read denied');
select is((select count(*) from public.contract where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and contract_id=pg_temp.hid('othercontract',1)),0::bigint,'cross-project contract read denied');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',1),pg_temp.hid('customer',1),'OUTBOUND','other-assignee')$$,'counselor can write another counselors assigned holder');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','grade-A',p_legacy_grade:='A')$$,'grade A allowed');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','grade-B',p_legacy_grade:='B')$$,'grade B allowed');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','grade-C',p_legacy_grade:='C')$$,'grade C allowed');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','grade-D',p_legacy_grade:='D')$$,'grade D allowed');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','grade-부재',p_legacy_grade:='부재')$$,'grade 부재 allowed');
select lives_ok($$select public.create_move_in_consultation('1283e198-5043-4027-96d6-edcc7a6686c6',pg_temp.hid('unit',3),pg_temp.hid('customer',3),'OUTBOUND','grade-상담거절',p_legacy_grade:='상담거절')$$,'grade 상담거절 allowed');
select is((select count(*) from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6' and content like 'grade-%' and created_by=pg_temp.hid('member',2)),6::bigint,'all grade writes have real actor');
select ok(not has_function_privilege('authenticated','private.require_field_customer_write_access(uuid,uuid,uuid)','EXECUTE'),'cannot spoof actor through private helper');
select ok(not has_function_privilege('anon','private.is_hwayang_field_member(uuid)','EXECUTE'),'anon cannot call membership helper');
select throws_ok($$select public.generate_report('1283e198-5043-4027-96d6-edcc7a6686c6',current_date,'SALES','DAILY','{}')$$,'42501',null,'non-field report phase stays admin-only');
select ok(not has_table_privilege('authenticated','public.project_member','UPDATE'),'role/activation direct write denied');
select ok(not has_table_privilege('authenticated','public.project','DELETE'),'project deletion denied');
reset role;
update public.project_member set active=false where id=pg_temp.hid('member',2);
set local role authenticated;
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),0::bigint,'inactive member read denied');
select throws_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','denied')$$,'42501',null,'inactive member write denied');
reset role;
select pg_temp.login('30000000-0000-4000-8000-0000000000c2');
set local role authenticated;
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),0::bigint,'nonmember admin read denied');
select throws_ok($$select public.generate_report('1283e198-5043-4027-96d6-edcc7a6686c6',current_date,'MOVE_IN','DAILY','{}')$$,'42501',null,'nonmember admin write denied');
reset role;
select pg_temp.login('');
set local role authenticated;
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),0::bigint,'missing auth read denied');
select throws_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','denied')$$,'42501',null,'missing auth write denied');
reset role;
set local role anon;
select throws_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','denied')$$,'42501',null,'anon RPC denied');
reset role;
-- 활성 멤버라도 닫힌 프로젝트/비활성 조직은 기존 경계대로 거절한다.
select pg_temp.login('30000000-0000-4000-8000-00000000000b');
update public.project set status='CLOSED' where id='1283e198-5043-4027-96d6-edcc7a6686c6';
set local role authenticated;
select is((select count(*) from public.consultation where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),0::bigint,'closed project shared history denied');
select throws_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','denied')$$,'42501',null,'closed project write denied');
reset role;
update public.project set status='ACTIVE' where id='1283e198-5043-4027-96d6-edcc7a6686c6';
update public.organization set status='INACTIVE' where id='10000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*) from public.customer where project_id='1283e198-5043-4027-96d6-edcc7a6686c6'),0::bigint,'inactive organization shared customers denied');
select throws_ok($$select public.save_brokerage_office('1283e198-5043-4027-96d6-edcc7a6686c6','denied')$$,'42501',null,'inactive organization write denied');
reset role;
select * from finish();
rollback;
